	it("opens /agents directly as the non-capturing work panel rather than a prompt-level selector", async () => {
		const commands = new Map<string, any>();
		const handlers = new Map<string, Array<(event: unknown, ctx: any) => unknown>>();
		const eventHandlers = new Map<string, Set<(data: unknown) => void>>();
		const screen = fakeTui(160, 40);
		const { custom } = fakeCustom(screen);
		const pi = {
			events: {
				on: (channel: string, handler: (data: unknown) => void) => {
					const listeners = eventHandlers.get(channel) ?? new Set();
					listeners.add(handler);
					eventHandlers.set(channel, listeners);
					return () => listeners.delete(handler);
				},
				emit: (channel: string, data: unknown) => {
					for (const listener of eventHandlers.get(channel) ?? []) listener(data);
				},
			},
			on: (name: string, handler: (event: unknown, ctx: any) => unknown) => {
				handlers.set(name, [...(handlers.get(name) ?? []), handler]);
			},
			registerShortcut: vi.fn(),
			registerCommand: (name: string, command: any) => commands.set(name, command),
			registerMessageRenderer: vi.fn(),
			registerTool: vi.fn(),
			sendMessage: vi.fn(),
		};
		installWorkManager(pi as any);
		installSubagents(pi as any);
		const ctx = {
			cwd: temporaryRoot(),
			hasUI: true,
			mode: "tui",
			isProjectTrusted: () => false,
			ui: { custom, select: vi.fn(), setWidget: vi.fn(), setStatus: vi.fn() },
		};

		try {
			await commands.get("agents").handler("", ctx);
			expect(screen.stack).toHaveLength(1);
			expect(screen.stack[0]!.options.nonCapturing).toBe(true);
			expect(screen.layout(screen.stack[0]!).lines.join("\n")).toContain("[Agents · 0]");
			expect(screen.focused()).toBe(screen.editor);
			expect(ctx.ui.select).not.toHaveBeenCalled();
		} finally {
			for (const handler of handlers.get("session_shutdown") ?? []) await handler({}, ctx);
		}
	});

	it("releases a nested foreground agent wait interrupted during startup", async () => {
		const root = temporaryRoot();
		mkdirSync(join(root, ".pi", "agents"), { recursive: true });
		writeFileSync(
			join(root, ".pi", "agents", "probe.md"),
			"---\nname: probe\ndescription: Test role\ntools: read\nskills: false\n---\n\nInspect.\n",
		);
		let settle!: () => void;
		const pending = new Promise<{ record: any }>((resolve) => {
			settle = () => resolve({ record: { status: "stopped" } });
		});
		const spawnAndWait = vi.fn(() => pending);
		const tools = createNestedSubagentTools({
			manager: { spawnAndWait } as any,
			pi: {} as any,
			parentAgentId: "parent",
			depth: 1,
			maxSubagentDepth: 2,
			allowedSubagents: "all",
			configCwd: root,
			projectTrusted: true,
		});
		const controller = new AbortController();
		const call = tools
			.find((tool) => tool.name === "agent")!
			.execute(
				"start",
				{
					prompt: "Inspect",
					description: "Inspect",
					subagent_type: "probe",
					run_in_background: false,
					isolated: false,
					inherit_context: false,
				} as any,
				controller.signal,
				undefined,
				{ model: { provider: "xai", id: "parent-model" }, modelRegistry: { find: vi.fn() } } as any,
			);
		try {
			controller.abort();
			const result = await Promise.race([call, new Promise((resolve) => setTimeout(() => resolve("waiting"), 50))]);
			expect(result).not.toBe("waiting");
			expect(result).toMatchObject({ isError: true });
			expect(spawnAndWait).toHaveBeenCalledOnce();
		} finally {
			settle();
		}
	});

	it("releases partial capacity when a queued start throws", () => {
		const manager = new AgentManager(undefined, 1);
		const record = { id: "queued", status: "queued", isBackground: true };
		(manager as any).agents.set(record.id, record);
		(manager as any).queue.push({
			id: record.id,
			start: () => {
				(manager as any).acquireCapacity(record);
				throw new Error("startup failed");
			},
		});
		(manager as any).drainQueue();
		expect(record).toMatchObject({ status: "error", error: "startup failed" });
		expect((manager as any).runningBackground).toBe(0);
		manager.dispose();
	});

